names = sorted(set(n.strip() for n in NAMES if n.strip()))
os.makedirs("src/lib", exist_ok=True)
with open(out, "w", encoding="utf-8", newline="\n") as f:
    f.write("// Common medicines used as a fallback for sound-alike matching on the voice prescription screen.\n")
    f.write("export const COMMON_MEDICINES: string[] = [\n" + "".join('  "%s",\n' % n for n in names) + "];\n")
with open(comp, "r", encoding="utf-8", newline="") as f: raw = f.read()
crlf = "\r\n" in raw
s = raw.replace("\r\n", "\n")
old = '  if (!catalogPromise) catalogPromise = searchDb("").catch(() => { catalogPromise = null; return []; });\n'
new = ('  if (!catalogPromise) catalogPromise = searchDb("").catch(() => [] as string[]).then(db => {\n'
       '    const seen = new Set(db.map(n => n.toLowerCase()));\n'
       '    return [...db, ...COMMON_MEDICINES.filter(n => !seen.has(n.toLowerCase()))];\n'
       '  });\n')
imp = '// the whole medicine list, loaded once'
if s.count(old) != 1 or s.count(imp) != 1: sys.exit("STOP: VoicePrescription.tsx doesn't match (is apply_soundmatch.py applied? already patched?). Nothing changed.")
s = s.replace(old, new).replace(imp, 'import { COMMON_MEDICINES } from "../lib/commonMedicines";\n\n' + imp)
with open(comp, "w", encoding="utf-8", newline="") as f: f.write(s.replace("\n", "\r\n") if crlf else s)
print("done:", len(names), "medicines added")
